    private Connection independent()throws SQLException { return DriverManager.getConnection(System.getenv("RMS_DB_URL"),System.getenv("RMS_DB_USERNAME"),System.getenv("RMS_DB_PASSWORD")); }
    private static Number scalar(Connection c,String sql,Object...args)throws SQLException { return MySqlGraphWriteExecutor.query(c,sql,args); }
    private void noOwner()throws SQLException { try(var c=independent()){assertNull(scalar(c,"SELECT IS_USED_LOCK(?)",MySqlGraphWriteExecutor.LOCK_NAME));} }
    private static int index(GraphTrace t,String event){var rows=t.events();for(int i=0;i<rows.size();i++)if(event.equals(rows.get(i).get("name")))return i;return -1;}
    private static void ordered(GraphTrace t,String...events){int previous=-1;for(String event:events){int value=index(t,event);assertTrue(value>previous,"Missing or misordered graph event "+event);previous=value;}}
    private JsonNode relation(JsonNode s,JsonNode t,String type,MockHttpSession session,int expected)throws Exception { return postJson("/api/v1/relations",session,Map.of("sourceRequirementId",s.get("requirementId").asText(),"targetRequirementId",t.get("requirementId").asText(),"relationType",type,"description","Synthetic relation description","expectedSourceLockVersion",s.get("lockVersion").asText(),"expectedTargetLockVersion",t.get("lockVersion").asText()),expected); }
