    @Test void allSixTypesNormalizationOriginalRevisionMappingAndDeleteAudit()throws Exception {
        MockHttpSession eng=login(user("REQUIREMENT_ENGINEER")),viewer=login(user("VIEWER"));var low=create(eng);var high=create(eng);high=patch(path(high)+"/content",eng,Map.of("title","High revised once","expectedLockVersion","0"),200);assertEquals("1",high.get("lockVersion").asText());assertEquals("INVALID_INPUT",relation(low,low,"DEPENDS_ON",eng,400).get("code").asText());
        var edges=new ArrayList<JsonNode>();for(String type:List.of("DEPENDS_ON","REFINES","DERIVED_FROM","CONFLICTS_WITH","DUPLICATES","RELATES_TO")){var e=relation(high,low,type,eng,201);edges.add(e);assertTrue(e.get("relationId").isTextual());boolean symmetric=List.of("CONFLICTS_WITH","DUPLICATES","RELATES_TO").contains(type);assertEquals((symmetric?low:high).get("requirementId"),e.get("sourceRequirementId"));assertEquals((symmetric?high:low).get("requirementId"),e.get("targetRequirementId"));relation(high,low,type,eng,409);if(symmetric)assertEquals("DUPLICATE",relation(low,high,type,eng,409).get("code").asText());}
        var swapped=new HashMap<String,Object>();swapped.put("sourceRequirementId",high.get("requirementId").asText());swapped.put("targetRequirementId",low.get("requirementId").asText());swapped.put("relationType","RELATES_TO");swapped.put("expectedSourceLockVersion","0");swapped.put("expectedTargetLockVersion","1");assertEquals("LOCK_VERSION_CONFLICT",postJson("/api/v1/relations",eng,swapped,409).get("code").asText());
        var page=getJson(path(low)+"/relations?size=2&page=1",viewer,200);assertEquals(6,page.get("totalElements").asInt());assertTrue(page.get("totalElements").isIntegralNumber());assertEquals(2,page.get("items").size());assertEquals(low,getJson(path(low),viewer,200));assertEquals(high,getJson(path(high),viewer,200));getJson(path(low)+"/relations?size=101",viewer,400);relation(high,low,"UNKNOWN",eng,400);relation(high,low,"REFINES",viewer,403);
        remove(edges.get(0),high,low,viewer,403);org.springframework.security.test.context.TestSecurityContextHolder.clearContext();String csrf=read(mvc.perform(get("/api/v1/auth/csrf").session(eng)).andReturn()).get("token").asText();mvc.perform(delete("/api/v1/relations/"+edges.get(0).get("relationId").asText()).session(eng).header("X-CSRF-TOKEN",csrf)).andExpect(status().isBadRequest());
        for(JsonNode e:edges){boolean normal=e.get("sourceRequirementId").equals(low.get("requirementId"));remove(e,normal?low:high,normal?high:low,eng,204);assertEquals(1,auditCount(e.get("relationId").asText(),"RELATION_REMOVE","SUCCESS"));JsonNode before=json.readTree((String)em.createNativeQuery("SELECT CAST(beforeData AS CHAR) FROM `AuditEvent` WHERE targetType='RELATION' AND targetId=:id AND action='RELATION_REMOVE' AND outcome='SUCCESS'").setParameter("id",e.get("relationId").asText()).getSingleResult());assertEquals(e.get("sourceRequirementId"),before.get("sourceRequirementId"));assertEquals(e.get("relationType"),before.get("relationType"));remove(e,normal?low:high,normal?high:low,eng,404);}
        assertEquals(0,getJson(path(low)+"/relations",viewer,200).get("items").size());assertEquals(low,getJson(path(low),eng,200));assertEquals(high,getJson(path(high),eng,200));noOwner();
    }
