        Created engineer=user("REQUIREMENT_ENGINEER");MockHttpSession eng=login(engineer),rev=login(user("REVIEWER")),viewer=login(user("VIEWER"));var a=create(eng);var b=create(eng);var edge=relation(a,b,"RELATES_TO",eng,201);assertEquals("STATE_CONFLICT",postJson(path(a)+"/withdraw",eng,Map.of("expectedLockVersion","0"),409).get("code").asText());remove(edge,a,b,eng,204);postJson(path(a)+"/withdraw",viewer,Map.of("expectedLockVersion","0"),403);postJson(path(a)+"/withdraw",eng,Map.of("expectedLockVersion","0","withdrawnBy","1"),400);var withdrawn=postJson(path(a)+"/withdraw",eng,Map.of("expectedLockVersion","0"),200);assertEquals(1,withdrawn.get("isWithdrawn").asInt());assertEquals("DRAFT",withdrawn.get("status").asText());assertEquals("1",withdrawn.get("lockVersion").asText());assertEquals(Long.toString(engineer.user().userId()),withdrawn.get("withdrawnBy").asText());assertFalse(withdrawn.get("withdrawnAt").isNull());assertEquals(a.get("title"),withdrawn.get("title"));assertEquals(withdrawn,getJson(path(a),viewer,200));var listing=getJson("/api/v1/requirements?keyword="+a.get("title").asText(),viewer,200);assertEquals(0,listing.get("items").size());assertEquals(0,getJson(path(a)+"/reviews",viewer,200).get("items").size());assertEquals(0,getJson(path(a)+"/relations",viewer,200).get("items").size());postJson(path(a)+"/withdraw",eng,Map.of("expectedLockVersion","1"),409);patch(path(a)+"/content",eng,Map.of("title","No edit","expectedLockVersion","1"),409);postJson(path(a)+"/comments",eng,Map.of("content","No new comment"),409);relation(withdrawn,b,"DEPENDS_ON",eng,409);
        var returned=create(eng);var round=submit(returned,eng);decision(round,rev,"REQUEST_CHANGES","1","Improve observable behavior",200);var draft=getJson(path(returned),eng,200);assertEquals("DRAFT",draft.get("status").asText());assertFalse(draft.get("firstSubmittedAt").isNull());postJson(path(draft)+"/withdraw",eng,Map.of("expectedLockVersion","2"),409);var rejected=create(eng);round=submit(rejected,eng);decision(round,rev,"REJECT","1","Synthetic rejected proposal",200);var reopened=postJson(path(rejected)+"/reopen",eng,Map.of("expectedLockVersion","2"),200);postJson(path(reopened)+"/withdraw",eng,Map.of("expectedLockVersion","3"),409);noOwner();
