    private RequirementData fixture(long actor){act(actor);return requirements.create("w4 "+UUID.randomUUID(),"Observable synthetic behavior","USER","FUNCTIONAL","HIGH","source","rationale","Saving displays the saved record").requirement();}
    @Test void productionExecutorSameConnectionHeldThroughCommitCompetingTimeoutAndRelease()throws Exception {
        Created engineer=user("REQUIREMENT_ENGINEER");var a=fixture(engineer.user().userId());var b=fixture(engineer.user().userId());Actor actor=access.requireEnabledActor(engineer.user().userId());var trace=new GraphTrace();var uncommitted=new CountDownLatch(1);var allowCommit=new CountDownLatch(1);var data=new LinkedHashMap<String,Object>();Future<RelationData> future;
        try(var workers=Executors.newSingleThreadExecutor()){future=workers.submit(()->graph.execute(trace,()->{var edge=writes.create(actor,a.requirementId(),b.requirementId(),"DEPENDS_ON",null,"0","0");uncommitted.countDown();assertTrue(allowCommit.await(10,TimeUnit.SECONDS));return edge;}));try{assertTrue(uncommitted.await(10,TimeUnit.SECONDS));try(var independent=independent()){long id=scalar(independent,"SELECT CONNECTION_ID()").longValue();assertNotEquals(trace.graphConnectionId,id);data.put("competingConnectionId",id);data.put("lockOwnerBeforeCommit",scalar(independent,"SELECT IS_USED_LOCK(?)",MySqlGraphWriteExecutor.LOCK_NAME));long started=System.nanoTime();var value=scalar(independent,"SELECT GET_LOCK(?,1)",MySqlGraphWriteExecutor.LOCK_NAME);long elapsed=TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-started);assertEquals(0,value.intValue());assertTrue(elapsed>=900);data.put("competingGetLockBeforeCommit",value.intValue());data.put("competingElapsedMs",elapsed);assertEquals(0,scalar(independent,"SELECT COUNT(*) FROM `RequirementRelation` WHERE sourceRequirementId=? AND targetRequirementId=?",a.requirementId(),b.requirementId()).intValue());}}finally{allowCommit.countDown();}var edge=future.get(15,TimeUnit.SECONDS);assertEquals(1,auditCount(Long.toString(edge.relationId()),"RELATION_CREATE","SUCCESS"));}
        assertEquals(trace.graphConnectionId,trace.jpaConnectionId);ordered(trace,"PHYSICAL_CONNECTION_PINNED","LOCK_ACQUIRED","TRANSACTION_CALLBACK_ENTERED","COMMIT_COMPLETED","SPRING_TRANSACTION_COMPLETION_AND_CLEANUP_RETURNED","RELEASE_LOCK_COMPLETED","POOL_RETURNED");try(var other=independent()){var value=scalar(other,"SELECT GET_LOCK(?,1)",MySqlGraphWriteExecutor.LOCK_NAME);assertEquals(1,value.intValue());data.put("competingGetLockAfterCommit",value.intValue());scalar(other,"SELECT RELEASE_LOCK(?)",MySqlGraphWriteExecutor.LOCK_NAME);}noOwner();data.put("productionExecution",trace.evidence());record("PRODUCTION_CONNECTION_COMMIT_RELEASE",data);
    }
    @Test void productionRollbackCleanupFaultEvictsWithoutFalseFailedAuditOrReplay()throws Exception {
        Created engineer=user("REQUIREMENT_ENGINEER");var a=fixture(engineer.user().userId());var b=fixture(engineer.user().userId());Actor actor=access.requireEnabledActor(engineer.user().userId());var rollback=new GraphTrace();long successes=((Number)em.createNativeQuery("SELECT COUNT(*) FROM `AuditEvent` WHERE action='RELATION_CREATE' AND outcome='SUCCESS'").getSingleResult()).longValue();assertThrows(MySqlGraphWriteExecutor.GraphWorkException.class,()->graph.execute(rollback,()->{writes.create(actor,a.requirementId(),b.requirementId(),"DEPENDS_ON",null,"0","0");throw new Exception("WAVE4_CHECKED_EXCEPTION_AFTER_WRITES");}));assertEquals(0,count("RequirementRelation","sourceRequirementId",a.requirementId()));assertEquals(successes,((Number)em.createNativeQuery("SELECT COUNT(*) FROM `AuditEvent` WHERE action='RELATION_CREATE' AND outcome='SUCCESS'").getSingleResult()).longValue());ordered(rollback,"ROLLBACK_COMPLETED","RELEASE_LOCK_COMPLETED","POOL_RETURNED");noOwner();
        assertThrows(org.springframework.transaction.IllegalTransactionStateException.class,()->writes.create(actor,a.requirementId(),b.requirementId(),"DEPENDS_ON",null,"0","0"));assertThrows(IllegalStateException.class,()->new TransactionTemplate(manager).executeWithoutResult(status->graph.execute(()->null)));
        var faultTrace=new GraphTrace();var bad=new MySqlGraphWriteExecutor(pool,pinned,(JpaTransactionManager)manager,em,c->scalar(c,"SELECT RMS_WAVE4_RELEASE_FAULT()"));GraphWriteExecutor observed=new GraphWriteExecutor(){public <T>T execute(Work<T> work){return bad.execute(faultTrace,work);}public void requireActive(){bad.requireActive();}};var facade=new RelationService(relationStore,writes,mutations,observed,current,failures);long failed=auditCount("NEW","RELATION_CREATE","FAILED");act(actor.userId());var failure=assertThrows(GraphOutcomeException.class,()->facade.create(Long.toString(a.requirementId()),Long.toString(b.requirementId()),"DEPENDS_ON",null,"0","0"));assertTrue(failure.committed());assertEquals(1,count("RequirementRelation","sourceRequirementId",a.requirementId()));assertEquals(successes+1,((Number)em.createNativeQuery("SELECT COUNT(*) FROM `AuditEvent` WHERE action='RELATION_CREATE' AND outcome='SUCCESS'").getSingleResult()).longValue());assertEquals(failed,auditCount("NEW","RELATION_CREATE","FAILED"));assertTrue(faultTrace.evicted);assertFalse(pinned.isPinned());assertEquals(-1,index(faultTrace,"POOL_RETURNED"));ordered(faultTrace,"COMMIT_COMPLETED","RELEASE_LOCK_FAILURE","CONNECTION_EVICTED_FROM_POOL","PHYSICAL_CONNECTION_ABORTED","EVICTED_HANDLE_CLOSED_NOT_NORMAL_POOL_RETURN");noOwner();var borrowed=new ArrayList<Long>();for(int i=0;i<4;i++)try(var c=pool.getConnection()){long id=scalar(c,"SELECT CONNECTION_ID()").longValue();assertNotEquals(faultTrace.graphConnectionId,id);borrowed.add(id);}var data=new LinkedHashMap<String,Object>();data.put("rollback",rollback.evidence());data.put("releaseFaultAfterCommit",faultTrace.evidence());data.put("borrowedConnectionIdsAfterEviction",borrowed);data.put("falseFailedAuditAdded",false);data.put("businessReplayed",false);data.put("isUsedLock",null);record("PRODUCTION_ROLLBACK_RELEASE_FAULT",data);
    }
    @Test void productionCompetingReverseDependenciesExactlyOneSuccessAndOneCycle()throws Exception {
        Created engineer=user("REQUIREMENT_ENGINEER");var a=fixture(engineer.user().userId());var b=fixture(engineer.user().userId());Actor actor=access.requireEnabledActor(engineer.user().userId());var traces=List.of(new GraphTrace(),new GraphTrace());var ready=new CountDownLatch(2);var start=new CountDownLatch(1);List<String> results=new ArrayList<>();try(var workers=Executors.newFixedThreadPool(2)){List<Future<String>> futures=new ArrayList<>();for(int i=0;i<2;i++){int index=i;futures.add(workers.submit(()->{ready.countDown();assertTrue(start.await(10,TimeUnit.SECONDS));try{graph.execute(traces.get(index),()->writes.create(actor,index==0?a.requirementId():b.requirementId(),index==0?b.requirementId():a.requirementId(),"DEPENDS_ON",null,"0","0"));return "SUCCESS";}catch(RmsException e){return e.code().name();}}));}assertTrue(ready.await(10,TimeUnit.SECONDS));start.countDown();for(var f:futures)results.add(f.get(20,TimeUnit.SECONDS));}assertEquals(1,Collections.frequency(results,"SUCCESS"));assertEquals(1,Collections.frequency(results,"DEPENDENCY_CYCLE"));assertEquals(1,count("RequirementRelation","sourceRequirementId",a.requirementId())+count("RequirementRelation","sourceRequirementId",b.requirementId()));for(var t:traces){assertEquals(t.graphConnectionId,t.jpaConnectionId);ordered(t,"LOCK_ACQUIRED","TRANSACTION_CALLBACK_ENTERED","RELEASE_LOCK_COMPLETED","POOL_RETURNED");}noOwner();record("PRODUCTION_COMPETING_CYCLE",Map.of("outcomes",results,"threads",traces.stream().map(GraphTrace::evidence).toList(),"finalEdgeCount",1));
    }
    @Test void productionWithdrawVersusRelationCreateHasOneWinnerAndAtomicFinalInvariant()throws Exception {
        Created engineer=user("REQUIREMENT_ENGINEER");var a=fixture(engineer.user().userId());var b=fixture(engineer.user().userId());Actor actor=access.requireEnabledActor(engineer.user().userId());var traces=List.of(new GraphTrace(),new GraphTrace());var barrier=new CyclicBarrier(2);List<String> results=new ArrayList<>();try(var workers=Executors.newFixedThreadPool(2)){var withdraw=workers.submit(()->{barrier.await(10,TimeUnit.SECONDS);try{graph.execute(traces.get(0),()->requirementWrites.withdraw(actor,a.requirementId(),"0"));return "SUCCESS";}catch(RmsException e){return e.code().name();}});var create=workers.submit(()->{barrier.await(10,TimeUnit.SECONDS);try{graph.execute(traces.get(1),()->writes.create(actor,a.requirementId(),b.requirementId(),"RELATES_TO",null,"0","0"));return "SUCCESS";}catch(RmsException e){return e.code().name();}});results.add(withdraw.get(20,TimeUnit.SECONDS));results.add(create.get(20,TimeUnit.SECONDS));}assertEquals(1,Collections.frequency(results,"SUCCESS"));assertEquals(1,Collections.frequency(results,"STATE_CONFLICT"));act(actor.userId());var finalParent=requirements.read(Long.toString(a.requirementId())).requirement();long edgeCount=count("RequirementRelation","sourceRequirementId",a.requirementId())+count("RequirementRelation","targetRequirementId",a.requirementId());assertTrue((finalParent.isWithdrawn()==1 && edgeCount==0) || (finalParent.isWithdrawn()==0 && edgeCount==1));noOwner();record("PRODUCTION_WITHDRAW_CREATE_COMPETITION",Map.of("outcomes",results,"isWithdrawn",finalParent.isWithdrawn(),"activeEdgeCount",edgeCount,"threads",traces.stream().map(GraphTrace::evidence).toList()));
    }
